const canvas=document.querySelector('canvas'),pick=document.querySelector('#model'),sequence=document.querySelector('#sequence'),status=document.querySelector('#status');
const lib=window.ModelViewer,viewer=new lib.viewer.ModelViewer(canvas,{alpha:false,antialias:true,preserveDrawingBuffer:true});viewer.addHandler(lib.viewer.handlers.mdx);viewer.addHandler(lib.viewer.handlers.blp);const scene=viewer.addScene();scene.viewport.set([0,0,640,500]);let instance,model,since=performance.now();
viewer.on('error',e=>status.textContent='Error: '+(e.error||e.message));
async function load(){if(instance)instance.detach();model=await viewer.load('assets/dialogue/source/'+pick.value+'_portrait.mdx',src=>'assets/dialogue/'+(/\.mdx$/i.test(src)?'source/':'portraits/')+src.split(/[\\/]/).at(-1));await viewer.whenAllLoaded();instance=model.addInstance();instance.setScene(scene);instance.setSequenceLoopMode(2);sequence.innerHTML=model.sequences.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('');sequence.value='1';reset();}
function reset(){instance.setSequence(Number(sequence.value));since=performance.now();}
sequence.onchange=reset;pick.onchange=load;
function draw(time){if(instance){const si=Number(sequence.value),s=model.sequences[si],frame=s.interval[0]+(time-since)%(s.interval[1]-s.interval[0]);instance.frame=frame;instance.forced=true;const c=model.cameras[0],a=new Float32Array(3),b=new Float32Array(3);c.getTranslation(a,si,frame,0);c.getTargetTranslation(b,si,frame,0);const p=Array.from(c.position,(v,i)=>v+a[i]),t=Array.from(c.targetPosition,(v,i)=>v+b[i]);scene.camera.perspective(c.fieldOfView,640/500,c.nearClippingPlane,c.farClippingPlane);scene.camera.moveToAndFace(p,t,[0,0,1]);viewer.update(0);viewer.render();status.textContent=`${s.name} · ${Math.round(frame-s.interval[0])} ms · FOV ${c.fieldOfView.toFixed(4)}`;}requestAnimationFrame(draw);}
await load();requestAnimationFrame(draw);
